if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('INSERT INTO journal(entry_date,title,subject,content,reflection,next_action) VALUES(?,?,?,?,?,?)')->execute([$_POST['entry_date']?:date('Y-m-d'),trim($_POST['title']??'Learning note'),trim($_POST['subject']??''),trim($_POST['content']??''),trim($_POST['reflection']??''),trim($_POST['next_action']??'')]);flash('Journal entry saved.');redirect('index.php?page=journal');}
$rows=db()->query('SELECT * FROM journal ORDER BY entry_date DESC,created_at DESC LIMIT 30')->fetchAll();
?><div class="page-heading"><div><p class="eyebrow">REFLECT & REMEMBER</p><h1>Learning Journal</h1><p class="muted">Capture what you learn, what challenges you and what comes next.</p></div></div><div class="two-col"><section class="card"><h2>New journal entry</h2><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Date</label><input type="date" name="entry_date" value="<?=date('Y-m-d')?>"><label>Title</label><input name="title" required><label>Subject</label><input name="subject"><label>What did you learn?</label><textarea name="content" rows="4"></textarea><label>Reflection / difficulty</label><textarea name="reflection" rows="3"></textarea><label>Next action</label><textarea name="next_action" rows="2"></textarea><button class="btn primary">Save entry</button></form></section><section class="card"><h2>Recent entries</h2><?php if(!$rows):?><div class="empty-state compact">Your learning journal is ready.</div><?php else:foreach($rows as $r):?><article class="journal-entry"><small class="muted"><?=e($r['entry_date'])?> · <?=e($r['subject'])?></small><h3><?=e($r['title'])?></h3><p><?=nl2br(e($r['content']))?></p><?php if($r['reflection']):?><small><b>Reflection:</b> <?=e($r['reflection'])?></small><?php endif;?></article><?php endforeach;endif;?></section></div>
